#!/usr/bin/env python3
"""Generate verified V134 Business Email & Domain Setup feature from V132."""
import base64,subprocess,sys,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
BASE="9987b17d2e5fc8b3aff74376ffaa8041d5100168"
TARGET="0978973680f0cdafa83d1d2742faa24193a8a779"
PATCH=""
def sha():
    return subprocess.check_output(["git","hash-object","app.py"],cwd=ROOT,text=True).strip()
def main():
    now=sha()
    if now==TARGET:
        print("Already V134");return
    if now!=BASE:
        raise SystemExit("Base app.py changed; refused to apply V134: "+now)
    patch=zlib.decompress(base64.b64decode(PATCH)).decode("utf-8")
    for command in (["git","apply","--check","--unidiff-zero"],["git","apply","--unidiff-zero"]):
        subprocess.run(command,cwd=ROOT,input=patch,text=True,check=True)
    if sha()!=TARGET:raise SystemExit("V134 source hash mismatch")
    subprocess.run([sys.executable,"-m","py_compile","app.py"],cwd=ROOT,check=True)
    print("Generated and verified V134 Business Email & Domain Setup")
if __name__=="__main__":main()
